function scoreKeywordMatches(text: string, keywords: ReadonlyArray<string>): number {
  let score = 0

  for (const keyword of keywords) {
    const normalizedKeyword = keyword.toLowerCase().trim()
    if (!normalizedKeyword) {
      continue
    }

    if (text.includes(normalizedKeyword)) {
      score += normalizedKeyword.length >= 3 ? 2 : 1

      if (text.startsWith(normalizedKeyword)) {
        score += 1
      }
    }
  }

  return score
}

export function normalizeArchiveCategory(input?: string | null): ArchiveCategory {
  if (!input) {
    return "기타"
  }

  const matched = ARCHIVE_CATEGORIES.find((category) => category === input)
  return matched || "기타"
}

export function isBroadArchiveCategory(category: ArchiveCategory): boolean {
  return BROAD_ARCHIVE_CATEGORY_SET.has(category)
}

export function detectArchiveCategory(text: string): ArchiveCategory {
  const normalizedText = (text || "").toLowerCase()
  let bestCategory: ArchiveCategory | null = null
  let bestScore = 0

  for (const rule of CATEGORY_RULES) {
    const score = scoreKeywordMatches(normalizedText, rule.keywords)

    if (score > bestScore) {
      bestScore = score
      bestCategory = rule.category
    }
  }

  if (bestCategory && bestScore > 0) {
    return bestCategory
  }

  const wuxiaScore = scoreKeywordMatches(normalizedText, WUXIA_CONTEXT_KEYWORDS)
  const fantasyScore = scoreKeywordMatches(normalizedText, FANTASY_CONTEXT_KEYWORDS)

  if (wuxiaScore === 0 && fantasyScore === 0) {
    return "기타"
  }

  return wuxiaScore >= fantasyScore ? "무협 기타" : "판타지 기타"
}

export function archiveCategoryToSlug(category: ArchiveCategory): string {
  return ARCHIVE_CATEGORY_SLUGS[category]
}

export function archiveSlugToCategory(slug?: string | null): ArchiveCategory | null {
  if (!slug) {
    return null
  }

  let decodedSlug = slug.toLowerCase()

  try {
    decodedSlug = decodeURIComponent(slug).toLowerCase()
  } catch {
    decodedSlug = slug.toLowerCase()
  }

  return ARCHIVE_SLUG_TO_CATEGORY[decodedSlug] || ARCHIVE_SLUG_ALIASES[decodedSlug] || null
}

export function getArchiveCategoryPath(category: ArchiveCategory): string {
  return `/search-archive/${archiveCategoryToSlug(category)}`
}
